def solve(payload):
    grouped = {}
    for event in payload.get('events', []):
        if event.get('at', 0) <= payload.get('as_of', 0):
            grouped.setdefault(event.get('id'), []).append(event)
    states = {}
    for ident, rows in grouped.items():
        rows.sort(key=lambda e: (e.get('seq', 0), e.get('at', 0)))
        state = None
        for event in rows:
            if event.get('op') == 'set': state = dict(event.get('value', {}))
            elif event.get('op') == 'patch' and state is not None: state.update(event.get('value', {}))
            elif event.get('op') == 'delete': state = None
        if state is not None: states[ident] = state
    return {'records': [{'id': i, 'name': states[i].get('name'), 'qty': states[i].get('qty')} for i in sorted(states)]}

def solve(payload):
    states = {}
    for event in payload.get('events', []):
        if event.get('at', 0) > payload.get('as_of', 0): continue
        ident = event.get('id')
        if event.get('op') == 'set': states[ident] = dict(event.get('value', {}))
        elif event.get('op') == 'patch': states.setdefault(ident, {}).update(event.get('value', {}))
        elif event.get('op') == 'delete': states.pop(ident, None)
    return {'records': [{'id': i, 'name': states[i].get('name'), 'qty': states[i].get('qty')} for i in sorted(states)]}
